{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Apply a 0.1 pairwise ranking margin across all four datasets to encourage greater positive-negative separation. Retain the 0.2 pointwise coefficient, uniform valid-position averaging, and one GRU4Rec checkpoint per category.",
      "edits": [
        {
          "find": "    pairwise_loss = torch.nn.functional.softplus(neg_scores - pos_scores)",
          "replace": "    pairwise_loss = torch.nn.functional.softplus(neg_scores - pos_scores + 0.1)"
        }
      ]
    }
  ],
  "change_summary": "Add only a 0.1 margin to the pairwise loss. Architecture, predictor, sampling, optimizer, routing, and training settings remain unchanged."
}
